import { answer } from "./engine.mjs";
const key = "static-preview-count";
let count = Number(localStorage.getItem(key) || 0);
const show = () => document.querySelector("#status").textContent = `Modules: ${answer}; storage: ${count}`;
document.querySelector("#increment").onclick = () => { localStorage.setItem(key, String(++count)); show(); };
show();
